mapper.select:
SELECT a.id, a.title, a.odd_number oddNumber, IFNULL(a.process_instance_id, '') processInstanceId, a.state, FORMAT(a.estimate_price, 2) estimatePrice, a.create_id createId, CONVERT(a.create_time, char) createTime, a.last_update_id lastUpdateId, CONVERT(a.last_update_time, char) lastUpdateTime FROM crm_opportunity a
${sqlExtract}
AND a.title LIKE CONCAT('%', #{keyword}, '%')
AND a.object_id = #{objectId}
ORDER BY a.create_time DESC
